type actionSnapshotThenLoader[Q orm.Loadable] struct {
	ActionActionLog func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildActionSnapshotThenLoader[Q orm.Loadable]() actionSnapshotThenLoader[Q] {
	type ActionActionLogLoadInterface interface {
		LoadActionActionLog(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return actionSnapshotThenLoader[Q]{
		ActionActionLog: thenLoadBuilder[Q](
			"ActionActionLog",
			func(ctx context.Context, exec bob.Executor, retrieved ActionActionLogLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadActionActionLog(ctx, exec, mods...)
			},
		),
	}
}

// LoadActionActionLog loads the actionSnapshot's ActionActionLog into the .R struct
func (o *ActionSnapshot) LoadActionActionLog(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.ActionActionLog = nil
	o.R.Loaded.ActionActionLog = false

	related, err := o.ActionActionLog(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.ActionActionSnapshots = ActionSnapshotSlice{o}

	o.R.ActionActionLog = related
	o.R.Loaded.ActionActionLog = true
	return nil
}

// LoadActionActionLog loads the actionSnapshot's ActionActionLog into the .R struct
func (os ActionSnapshotSlice) LoadActionActionLog(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	actionLogs, err := os.ActionActionLog(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.ActionActionLog = nil
		o.R.Loaded.ActionActionLog = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	actionSnapshotByKey := make(map[int64][]*ActionSnapshot, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		actionSnapshotByKey[o.ActionID] = append(actionSnapshotByKey[o.ActionID], o)
	}

	for _, rel := range actionLogs {

		owners, ok := actionSnapshotByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.ActionActionLog != nil {
				continue
			}

			rel.R.ActionActionSnapshots = append(rel.R.ActionActionSnapshots, o)

			o.R.ActionActionLog = rel

		}
	}

	return nil
}

type actionSnapshotJoins[Q dialect.Joinable] struct {
	typ             string
	ActionActionLog modAs[Q, actionLogColumns]
}

func (j actionSnapshotJoins[Q]) aliasedAs(alias string) actionSnapshotJoins[Q] {
	return buildActionSnapshotJoins[Q](buildActionSnapshotColumns(alias), j.typ)
}

func buildActionSnapshotJoins[Q dialect.Joinable](cols actionSnapshotColumns, typ string) actionSnapshotJoins[Q] {
	return actionSnapshotJoins[Q]{
		typ: typ,
		ActionActionLog: modAs[Q, actionLogColumns]{
			c: ActionLogs.Columns,
			f: func(to actionLogColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, ActionLogs.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.ActionID),
					))
				}

				return mods
			},
		},
	}
}
